using LawLms.Application;
using LawLms.Domain;
using Microsoft.EntityFrameworkCore;

namespace LawLms.Infrastructure.Persistence;

public sealed class LmsDbContext(DbContextOptions<LmsDbContext> options) : DbContext(options), IUnitOfWork
{
    public DbSet<AppUser> Users => Set<AppUser>(); public DbSet<Course> Courses => Set<Course>(); public DbSet<Lesson> Lessons => Set<Lesson>(); public DbSet<Enrollment> Enrollments => Set<Enrollment>(); public DbSet<TeachingClass> TeachingClasses => Set<TeachingClass>(); public DbSet<LibraryResource> LibraryResources => Set<LibraryResource>(); public DbSet<Quiz> Quizzes => Set<Quiz>(); public DbSet<QuizQuestion> QuizQuestions => Set<QuizQuestion>(); public DbSet<QuizAttempt> QuizAttempts => Set<QuizAttempt>(); public DbSet<QuizAnswer> QuizAnswers => Set<QuizAnswer>();
    public DbSet<Notification> Notifications => Set<Notification>();
    public DbSet<QuizAllowance> QuizAllowances => Set<QuizAllowance>();
    public DbSet<OfferingEnrollment> OfferingEnrollments => Set<OfferingEnrollment>();
    public DbSet<LessonCompletion> LessonCompletions => Set<LessonCompletion>();
    public DbSet<AuditEntry> AuditEntries => Set<AuditEntry>();
    public DbSet<GradeAppeal> GradeAppeals => Set<GradeAppeal>();
    public DbSet<ScheduleEvent> ScheduleEvents => Set<ScheduleEvent>();
    public DbSet<ScheduleChange> ScheduleChanges => Set<ScheduleChange>();
    public DbSet<AttendanceRecord> AttendanceRecords => Set<AttendanceRecord>();
    public DbSet<ForumTopic> ForumTopics => Set<ForumTopic>();
    public DbSet<ForumReply> ForumReplies => Set<ForumReply>();
    public DbSet<ForumSubscription> ForumSubscriptions => Set<ForumSubscription>();
    public DbSet<BankQuestion> BankQuestions => Set<BankQuestion>();
    protected override void OnModelCreating(ModelBuilder model)
    {
        model.Entity<AppUser>(e => { e.ToTable("users"); e.Property(x => x.Id).HasColumnName("id"); e.Property(x => x.FullName).HasColumnName("full_name").HasMaxLength(200); e.Property(x => x.Email).HasColumnName("email").HasMaxLength(256); e.Property(x => x.PasswordHash).HasColumnName("password_hash"); e.Property(x => x.Role).HasColumnName("role"); e.Property(x => x.IsActive).HasColumnName("is_active"); e.Property(x => x.MustChangePassword).HasColumnName("must_change_password"); e.Property(x => x.TokenVersion).HasColumnName("token_version"); e.Property(x => x.ClassCode).HasColumnName("class_code").HasMaxLength(30); e.Property(x => x.CreatedAt).HasColumnName("created_at"); e.HasIndex(x => x.Email).IsUnique(); });
        model.Entity<Course>(e => { e.ToTable("courses"); e.Property(x => x.Id).HasColumnName("id"); e.Property(x => x.Code).HasColumnName("code").HasMaxLength(30); e.Property(x => x.Title).HasColumnName("title").HasMaxLength(300); e.Property(x => x.Description).HasColumnName("description"); e.Property(x => x.Category).HasColumnName("category"); e.Property(x => x.Color).HasColumnName("color"); e.Property(x => x.IsPublished).HasColumnName("is_published"); e.Property(x => x.Status).HasColumnName("status"); e.Property(x => x.Revision).HasColumnName("revision").IsConcurrencyToken(); e.Property(x => x.ReviewHistoryJson).HasColumnName("review_history_json"); e.Property(x => x.LecturerId).HasColumnName("lecturer_id"); e.Property(x => x.CreatedAt).HasColumnName("created_at"); e.HasIndex(x => x.Code).IsUnique(); e.HasOne(x => x.Lecturer).WithMany(x => x.CoursesTaught).HasForeignKey(x => x.LecturerId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<Lesson>(e => { e.ToTable("lessons"); e.Property(x => x.Id).HasColumnName("id"); e.Property(x => x.CourseId).HasColumnName("course_id"); e.Property(x => x.Title).HasColumnName("title").HasMaxLength(300); e.Property(x => x.Content).HasColumnName("content"); e.Property(x => x.Position).HasColumnName("position"); e.Property(x => x.DurationMinutes).HasColumnName("duration_minutes"); e.HasOne(x => x.Course).WithMany(x => x.Lessons).HasForeignKey(x => x.CourseId).OnDelete(DeleteBehavior.Cascade); });
        model.Entity<Enrollment>(e => { e.ToTable("enrollments"); e.Property(x => x.Id).HasColumnName("id"); e.Property(x => x.UserId).HasColumnName("user_id"); e.Property(x => x.CourseId).HasColumnName("course_id"); e.Property(x => x.ProgressPercent).HasColumnName("progress_percent"); e.Property(x => x.EnrolledAt).HasColumnName("enrolled_at"); e.HasIndex(x => new { x.UserId, x.CourseId }).IsUnique(); e.HasOne(x => x.User).WithMany(x => x.Enrollments).HasForeignKey(x => x.UserId); e.HasOne(x => x.Course).WithMany(x => x.Enrollments).HasForeignKey(x => x.CourseId); });
        model.Entity<TeachingClass>(e => { e.ToTable("teaching_classes"); e.Property(x => x.Id).HasColumnName("id"); e.Property(x => x.Code).HasColumnName("code").HasMaxLength(30); e.Property(x => x.Name).HasColumnName("name").HasMaxLength(200); e.Property(x => x.CourseId).HasColumnName("course_id"); e.Property(x => x.CourseTitle).HasColumnName("course_title").HasMaxLength(300); e.Property(x => x.AcademicYear).HasColumnName("academic_year").HasMaxLength(30); e.Property(x => x.Term).HasColumnName("term").HasMaxLength(30); e.Property(x => x.Status).HasColumnName("status"); e.Property(x => x.StartsAt).HasColumnName("starts_at"); e.Property(x => x.EndsAt).HasColumnName("ends_at"); e.Property(x => x.PassingGrade).HasColumnName("passing_grade").HasPrecision(5,2); e.Property(x => x.RequiredProgress).HasColumnName("required_progress"); e.Property(x => x.AppealDays).HasColumnName("appeal_days"); e.Property(x => x.GradeStatus).HasColumnName("grade_status"); e.Property(x => x.GradesPublishedAt).HasColumnName("grades_published_at"); e.Property(x => x.Revision).HasColumnName("revision").IsConcurrencyToken(); e.Property(x => x.PrimaryLecturerId).HasColumnName("primary_lecturer_id"); e.Property(x => x.AssistantLecturerOneId).HasColumnName("assistant_lecturer_one_id"); e.Property(x => x.AssistantLecturerTwoId).HasColumnName("assistant_lecturer_two_id"); e.Property(x => x.AssignedAt).HasColumnName("assigned_at"); e.HasIndex(x => new { x.Code, x.CourseId, x.AcademicYear, x.Term }).IsUnique(); e.HasOne<Course>().WithMany().HasForeignKey(x => x.CourseId).OnDelete(DeleteBehavior.Restrict); e.HasOne<AppUser>().WithMany().HasForeignKey(x => x.PrimaryLecturerId).OnDelete(DeleteBehavior.Restrict); e.HasOne<AppUser>().WithMany().HasForeignKey(x => x.AssistantLecturerOneId).OnDelete(DeleteBehavior.Restrict); e.HasOne<AppUser>().WithMany().HasForeignKey(x => x.AssistantLecturerTwoId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<LibraryResource>(e => { e.ToTable("library_resources"); e.Property(x => x.Id).HasColumnName("id"); e.Property(x => x.Title).HasColumnName("title").HasMaxLength(300); e.Property(x => x.Description).HasColumnName("description"); e.Property(x => x.Category).HasColumnName("category").HasMaxLength(100); e.Property(x => x.OriginalFileName).HasColumnName("original_file_name").HasMaxLength(300); e.Property(x => x.StoredFileName).HasColumnName("stored_file_name").HasMaxLength(300); e.Property(x => x.ContentType).HasColumnName("content_type").HasMaxLength(150); e.Property(x => x.SizeBytes).HasColumnName("size_bytes"); e.Property(x => x.UploadedById).HasColumnName("uploaded_by_id"); e.Property(x => x.UploadedAt).HasColumnName("uploaded_at"); e.HasOne<AppUser>().WithMany().HasForeignKey(x => x.UploadedById).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<Quiz>(e => { e.Property(x=>x.ShuffleQuestions).HasColumnName("shuffle_questions"); e.Property(x=>x.ShuffleOptions).HasColumnName("shuffle_options"); e.Property(x => x.TeachingClassId).HasColumnName("teaching_class_id"); e.HasOne<TeachingClass>().WithMany().HasForeignKey(x => x.TeachingClassId).OnDelete(DeleteBehavior.Restrict); e.Property(x => x.Weight).HasColumnName("weight").HasPrecision(5,2); e.Property(x => x.MultipleChoiceWeight).HasColumnName("multiple_choice_weight").HasPrecision(5,2); e.Property(x => x.EssayWeight).HasColumnName("essay_weight").HasPrecision(5,2); e.Property(x => x.Revision).HasColumnName("revision").IsConcurrencyToken(); e.ToTable("quizzes"); e.Property(x => x.Id).HasColumnName("id"); e.Property(x => x.CourseId).HasColumnName("course_id"); e.Property(x => x.ClassCode).HasColumnName("class_code").HasMaxLength(30); e.Property(x => x.CreatedById).HasColumnName("created_by_id"); e.Property(x => x.Title).HasColumnName("title").HasMaxLength(300); e.Property(x => x.Description).HasColumnName("description"); e.Property(x => x.DurationMinutes).HasColumnName("duration_minutes"); e.Property(x => x.AttemptsAllowed).HasColumnName("attempts_allowed"); e.Property(x => x.PassingScore).HasColumnName("passing_score").HasPrecision(8, 2); e.Property(x => x.OpensAt).HasColumnName("opens_at"); e.Property(x => x.ClosesAt).HasColumnName("closes_at"); e.Property(x => x.Status).HasColumnName("status"); e.Property(x => x.CreatedAt).HasColumnName("created_at"); e.HasIndex(x => new { x.CourseId, x.ClassCode }); e.HasOne<Course>().WithMany().HasForeignKey(x => x.CourseId).OnDelete(DeleteBehavior.Restrict); e.HasOne<AppUser>().WithMany().HasForeignKey(x => x.CreatedById).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<QuizQuestion>(e => { e.ToTable("quiz_questions"); e.Property(x => x.Id).HasColumnName("id"); e.Property(x => x.QuizId).HasColumnName("quiz_id"); e.Property(x => x.Content).HasColumnName("content"); e.Property(x => x.Type).HasColumnName("type"); e.Property(x => x.OptionsJson).HasColumnName("options_json"); e.Property(x => x.CorrectAnswer).HasColumnName("correct_answer"); e.Property(x => x.Points).HasColumnName("points").HasPrecision(8, 2); e.Property(x => x.Position).HasColumnName("position"); e.HasOne(x => x.Quiz).WithMany(x => x.Questions).HasForeignKey(x => x.QuizId).OnDelete(DeleteBehavior.Cascade); });
        model.Entity<QuizAttempt>(e => { e.Property(x=>x.QuestionOrderJson).HasColumnName("question_order_json"); e.Property(x=>x.OptionOrderJson).HasColumnName("option_order_json"); e.Property(x => x.ExpiresAt).HasColumnName("expires_at"); e.Property(x => x.Status).HasColumnName("status"); e.Property(x => x.Revision).HasColumnName("revision").IsConcurrencyToken(); e.HasIndex(x => new { x.QuizId, x.StudentId }).IsUnique().HasFilter("status = 0").HasDatabaseName("uq_attempt_in_progress"); e.ToTable("quiz_attempts"); e.Property(x => x.Id).HasColumnName("id"); e.Property(x => x.QuizId).HasColumnName("quiz_id"); e.Property(x => x.StudentId).HasColumnName("student_id"); e.Property(x => x.StartedAt).HasColumnName("started_at"); e.Property(x => x.SubmittedAt).HasColumnName("submitted_at"); e.Property(x => x.AutoScore).HasColumnName("auto_score").HasPrecision(8, 2); e.Property(x => x.FinalScore).HasColumnName("final_score").HasPrecision(8, 2); e.HasIndex(x => new { x.QuizId, x.StudentId }); e.HasOne<Quiz>().WithMany().HasForeignKey(x => x.QuizId).OnDelete(DeleteBehavior.Cascade); e.HasOne<AppUser>().WithMany().HasForeignKey(x => x.StudentId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<QuizAnswer>(e => { e.Property(x => x.Feedback).HasColumnName("feedback"); e.HasIndex(x => new { x.AttemptId, x.QuestionId }).IsUnique(); e.ToTable("quiz_answers"); e.Property(x => x.Id).HasColumnName("id"); e.Property(x => x.AttemptId).HasColumnName("attempt_id"); e.Property(x => x.QuestionId).HasColumnName("question_id"); e.Property(x => x.Answer).HasColumnName("answer"); e.Property(x => x.Score).HasColumnName("score").HasPrecision(8, 2); e.HasOne<QuizAttempt>().WithMany(x => x.Answers).HasForeignKey(x => x.AttemptId).OnDelete(DeleteBehavior.Cascade); e.HasOne<QuizQuestion>().WithMany().HasForeignKey(x => x.QuestionId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<OfferingEnrollment>(e => { e.ToTable("offering_enrollments"); e.HasKey(x => x.Id); e.Property(x => x.Id).HasColumnName("id"); e.Property(x => x.TeachingClassId).HasColumnName("teaching_class_id"); e.Property(x => x.UserId).HasColumnName("user_id"); e.Property(x => x.Status).HasColumnName("status"); e.Property(x => x.EnrolledAt).HasColumnName("enrolled_at"); e.HasIndex(x => new { x.TeachingClassId, x.UserId }).IsUnique(); e.HasOne<TeachingClass>().WithMany().HasForeignKey(x => x.TeachingClassId).OnDelete(DeleteBehavior.Restrict); e.HasOne<AppUser>().WithMany().HasForeignKey(x => x.UserId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<LessonCompletion>(e => { e.ToTable("lesson_completions"); e.HasKey(x => x.Id); e.Property(x => x.Id).HasColumnName("id"); e.Property(x => x.EnrollmentId).HasColumnName("enrollment_id"); e.Property(x => x.LessonId).HasColumnName("lesson_id"); e.Property(x => x.CompletedAt).HasColumnName("completed_at"); e.HasIndex(x => new { x.EnrollmentId, x.LessonId }).IsUnique(); e.HasOne<OfferingEnrollment>().WithMany().HasForeignKey(x => x.EnrollmentId).OnDelete(DeleteBehavior.Restrict); e.HasOne<Lesson>().WithMany().HasForeignKey(x => x.LessonId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<AuditEntry>(e => { e.ToTable("audit_entries"); e.HasKey(x => x.Id); e.Property(x => x.Id).HasColumnName("id"); e.Property(x => x.ActorId).HasColumnName("actor_id"); e.Property(x => x.EntityId).HasColumnName("entity_id"); e.Property(x => x.Action).HasColumnName("action"); e.Property(x => x.Detail).HasColumnName("detail"); e.Property(x => x.At).HasColumnName("at"); e.HasIndex(x => x.EntityId); });
        model.Entity<GradeAppeal>(e => { e.Property(x => x.ProposedGradesJson).HasColumnName("proposed_grades_json"); e.ToTable("grade_appeals"); e.HasKey(x => x.Id); e.Property(x => x.Id).HasColumnName("id"); e.Property(x => x.TeachingClassId).HasColumnName("teaching_class_id"); e.Property(x => x.StudentId).HasColumnName("student_id"); e.Property(x => x.AttemptId).HasColumnName("attempt_id"); e.Property(x => x.Reason).HasColumnName("reason"); e.Property(x => x.Resolution).HasColumnName("resolution"); e.Property(x => x.ReviewerId).HasColumnName("reviewer_id"); e.Property(x => x.Status).HasColumnName("status"); e.Property(x => x.CreatedAt).HasColumnName("created_at"); e.Property(x => x.Revision).HasColumnName("revision").IsConcurrencyToken(); e.HasOne<TeachingClass>().WithMany().HasForeignKey(x => x.TeachingClassId).OnDelete(DeleteBehavior.Restrict); e.HasOne<QuizAttempt>().WithMany().HasForeignKey(x => x.AttemptId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<Notification>(e => { e.ToTable("notifications"); e.HasKey(x=>x.Id); e.Property(x=>x.Id).HasColumnName("id"); e.Property(x=>x.UserId).HasColumnName("user_id"); e.Property(x=>x.TeachingClassId).HasColumnName("teaching_class_id"); e.Property(x=>x.DedupKey).HasColumnName("dedup_key"); e.Property(x=>x.Message).HasColumnName("message"); e.Property(x=>x.CreatedAt).HasColumnName("created_at"); e.Property(x=>x.ReadAt).HasColumnName("read_at"); e.HasIndex(x=>new{x.UserId,x.DedupKey}).IsUnique(); });
        model.Entity<QuizAllowance>(e => { e.ToTable("quiz_allowances"); e.HasKey(x=>x.Id); e.Property(x=>x.Id).HasColumnName("id"); e.Property(x=>x.QuizId).HasColumnName("quiz_id"); e.Property(x=>x.StudentId).HasColumnName("student_id"); e.Property(x=>x.ExtraAttempts).HasColumnName("extra_attempts"); e.Property(x=>x.ExtendedUntil).HasColumnName("extended_until"); e.HasIndex(x=>new{x.QuizId,x.StudentId}).IsUnique(); });
        model.Entity<ScheduleEvent>(e => { e.ToTable("schedule_events"); e.HasKey(x=>x.Id); e.Property(x=>x.Id).HasColumnName("id"); e.Property(x=>x.TeachingClassId).HasColumnName("teaching_class_id"); e.Property(x=>x.Type).HasColumnName("type"); e.Property(x=>x.Title).HasColumnName("title").HasMaxLength(300); e.Property(x=>x.Room).HasColumnName("room").HasMaxLength(100); e.Property(x=>x.Location).HasColumnName("location").HasMaxLength(300); e.Property(x=>x.Notes).HasColumnName("notes").HasMaxLength(4000); e.Property(x=>x.StartsAt).HasColumnName("starts_at"); e.Property(x=>x.EndsAt).HasColumnName("ends_at"); e.Property(x=>x.IsCancelled).HasColumnName("is_cancelled"); e.Property(x=>x.Revision).HasColumnName("revision").IsConcurrencyToken(); e.Property(x=>x.CreatedById).HasColumnName("created_by_id"); e.Property(x=>x.CreatedAt).HasColumnName("created_at"); e.Property(x=>x.UpdatedAt).HasColumnName("updated_at"); e.HasIndex(x=>new{x.TeachingClassId,x.StartsAt}); e.HasOne<TeachingClass>().WithMany().HasForeignKey(x=>x.TeachingClassId).OnDelete(DeleteBehavior.Restrict); e.HasOne<AppUser>().WithMany().HasForeignKey(x=>x.CreatedById).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<ScheduleChange>(e => { e.ToTable("schedule_changes"); e.HasKey(x=>x.Id); e.Property(x=>x.Id).HasColumnName("id"); e.Property(x=>x.ScheduleEventId).HasColumnName("schedule_event_id"); e.Property(x=>x.ActorId).HasColumnName("actor_id"); e.Property(x=>x.Action).HasColumnName("action").HasMaxLength(30); e.Property(x=>x.SnapshotJson).HasColumnName("snapshot_json").HasColumnType("jsonb"); e.Property(x=>x.At).HasColumnName("at"); e.HasIndex(x=>new{x.ScheduleEventId,x.At}); e.HasOne<ScheduleEvent>().WithMany().HasForeignKey(x=>x.ScheduleEventId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<AttendanceRecord>(e => { e.ToTable("attendance_records"); e.HasKey(x=>x.Id); e.Property(x=>x.Id).HasColumnName("id"); e.Property(x=>x.ScheduleEventId).HasColumnName("schedule_event_id"); e.Property(x=>x.StudentId).HasColumnName("student_id"); e.Property(x=>x.Status).HasColumnName("status"); e.Property(x=>x.MarkedById).HasColumnName("marked_by_id"); e.Property(x=>x.MarkedAt).HasColumnName("marked_at"); e.HasIndex(x=>new{x.ScheduleEventId,x.StudentId}).IsUnique(); e.HasOne<ScheduleEvent>().WithMany().HasForeignKey(x=>x.ScheduleEventId).OnDelete(DeleteBehavior.Restrict); e.HasOne<AppUser>().WithMany().HasForeignKey(x=>x.StudentId).OnDelete(DeleteBehavior.Restrict); e.HasOne<AppUser>().WithMany().HasForeignKey(x=>x.MarkedById).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<ForumTopic>(e => { e.ToTable("forum_topics"); e.HasKey(x=>x.Id); e.Property(x=>x.Id).HasColumnName("id"); e.Property(x=>x.TeachingClassId).HasColumnName("teaching_class_id"); e.Property(x=>x.AuthorId).HasColumnName("author_id"); e.Property(x=>x.Title).HasColumnName("title").HasMaxLength(200); e.Property(x=>x.Body).HasColumnName("body").HasMaxLength(10000); e.Property(x=>x.CreatedAt).HasColumnName("created_at"); e.Property(x=>x.LastActivityAt).HasColumnName("last_activity_at"); e.Property(x=>x.Revision).HasColumnName("revision"); e.HasIndex(x=>new{x.TeachingClassId,x.LastActivityAt}); e.HasOne<TeachingClass>().WithMany().HasForeignKey(x=>x.TeachingClassId).OnDelete(DeleteBehavior.Restrict); e.HasOne<AppUser>().WithMany().HasForeignKey(x=>x.AuthorId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<ForumReply>(e => { e.ToTable("forum_replies"); e.HasKey(x=>x.Id); e.Property(x=>x.Id).HasColumnName("id"); e.Property(x=>x.TopicId).HasColumnName("topic_id"); e.Property(x=>x.AuthorId).HasColumnName("author_id"); e.Property(x=>x.Body).HasColumnName("body").HasMaxLength(10000); e.Property(x=>x.IsPinnedAnswer).HasColumnName("is_pinned_answer"); e.Property(x=>x.CreatedAt).HasColumnName("created_at"); e.HasIndex(x=>x.TopicId); e.HasIndex(x=>x.TopicId).IsUnique().HasFilter("is_pinned_answer").HasDatabaseName("uq_forum_one_pinned_answer"); e.HasOne<ForumTopic>().WithMany().HasForeignKey(x=>x.TopicId).OnDelete(DeleteBehavior.Restrict); e.HasOne<AppUser>().WithMany().HasForeignKey(x=>x.AuthorId).OnDelete(DeleteBehavior.Restrict); });
        model.Entity<BankQuestion>(e => {
            e.ToTable("bank_questions"); e.HasKey(x=>x.Id);
            e.Property(x=>x.Id).HasColumnName("id"); e.Property(x=>x.CourseId).HasColumnName("course_id"); e.Property(x=>x.CreatedById).HasColumnName("created_by_id");
            e.Property(x=>x.Content).HasColumnName("content"); e.Property(x=>x.Type).HasColumnName("type"); e.Property(x=>x.OptionsJson).HasColumnName("options_json"); e.Property(x=>x.CorrectAnswer).HasColumnName("correct_answer");
            e.Property(x=>x.Points).HasColumnName("points").HasPrecision(8,2); e.Property(x=>x.Topic).HasColumnName("topic").HasMaxLength(200); e.Property(x=>x.Difficulty).HasColumnName("difficulty"); e.Property(x=>x.Source).HasColumnName("source");
            e.Property(x=>x.Fingerprint).HasColumnName("fingerprint").HasMaxLength(64); e.Property(x=>x.IsArchived).HasColumnName("is_archived"); e.Property(x=>x.Revision).HasColumnName("revision").IsConcurrencyToken();
            e.Property(x=>x.CreatedAt).HasColumnName("created_at"); e.Property(x=>x.UpdatedAt).HasColumnName("updated_at");
            e.HasOne<Course>().WithMany().HasForeignKey(x=>x.CourseId).OnDelete(DeleteBehavior.Restrict); e.HasOne<AppUser>().WithMany().HasForeignKey(x=>x.CreatedById).OnDelete(DeleteBehavior.Restrict);
            e.HasIndex(x=>new{x.CourseId,x.CreatedById,x.Fingerprint}).IsUnique();
        });
        model.Entity<ForumSubscription>(e => { e.ToTable("forum_subscriptions"); e.HasKey(x=>new{x.TopicId,x.UserId}); e.Property(x=>x.TopicId).HasColumnName("topic_id"); e.Property(x=>x.UserId).HasColumnName("user_id"); e.Property(x=>x.SubscribedAt).HasColumnName("subscribed_at"); e.HasOne<ForumTopic>().WithMany().HasForeignKey(x=>x.TopicId).OnDelete(DeleteBehavior.Cascade); e.HasOne<AppUser>().WithMany().HasForeignKey(x=>x.UserId).OnDelete(DeleteBehavior.Cascade); });
    }
}
